@dataclass
class PromptContext:
    """Inputs for building LLM messages on one turn.

    ``active_target`` is the active skill's
    :class:`~rasa.mantle.skills.catalog.ResolvedActivationTarget` (every active frame
    resolves to one — prose entries use a virtual autonomous step); ``turn``
    carries the channel modality via ``turn.is_voice``.

    ``memory_values`` is the schema-scoped value view for the active skill
    (``SkillExecutor.current_memory_values``), keyed by fully-qualified slot
    name. Routing gating, tool schemas, and instruction filtering use this
    dict rather than raw tracker slots, so what the LLM sees matches what the
    executor permits at dispatch time (public/private/project and cross-skill
    scoping honoured). Empty for rephrase calls, which omit the skill/routing
    sections
    entirely.

    ``memory_entries`` is the parallel ``MemoryEntry`` view
    (``SkillExecutor.current_memory_entries`` → ``MemoryManager.read_all``)
    used to render the active-skill ``### Memory:`` listing (set values; PII
    shown as ``[set]`` without the raw value) and to substitute ``@memory``
    tokens in instruction prose. Prefer populating both from one
    ``current_memory_entries`` call so the listing and gating cannot drift.
    """

    tracker: Optional[DialogueStateTracker]
    bootstrap: ModelBootstrap
    turn: IncomingTurn
    active_target: Optional[ResolvedActivationTarget] = field(default=None)
    active_skill_id: Optional[str] = field(default=None)
    memory_values: dict = field(default_factory=dict)
    memory_entries: dict = field(default_factory=dict)
    max_utterances: int = DEFAULT_MAX_UTTERANCES
    # Set after a correction rewind cleared stale downstream memory, so the
    # active-skill prompt can warn the LLM to re-set safe values from history and
    # re-ask any that depend on the corrected one. Sourced from the persisted
    # ``system.*`` resume point (``TrackerHandle.correction_in_progress``), so it
    # can stay set across multiple turns — until the re-walk reaches the trigger
    # step again or the owning frame completes and leaves the stack.
    memory_cleared_by_correction: bool = False
    # True when this turn offers the ``correct`` tool (at least one earlier
    # value is correctable). Gates the active-skill correction reminder so the
    # prompt never tells the LLM to call a tool absent from the turn's schema.
    correct_tool_available: bool = False
    # Pending confirmation when a builder tool is paused on ``requires_confirmation``.
    # Gates the pending-confirmation reminder and must stay in sync with the
    # ``resolve_tool_confirmation`` schema offered for the same turn.
    pending_tool_confirmation: Optional[PendingToolConfirmation] = None
    # ``search_knowledge`` has been called this turn. The active skill's
    # fine-grained instructions are dropped from the prompt (only its
    # name/description stay) so the grounded answer does not also re-drive the
    # skill's steps.
    knowledge_searched: bool = False
    # The acknowledgement guidance (section + examples) belongs only on the
    # turn's first LLM call; later loop iterations omit it. Defaults True so a
    # prompt built outside the loop behaves like the opening call. The
    # orchestrator sets it False from the second LLM iteration onward, mirroring
    # its own ack-reminder gate.
    is_first_llm_iteration: bool = True
    # False on a text collect step, on a voice collect step whose question has
    # not been asked yet, and while a post-search answer or pending tool
    # confirmation owns the LLM call. The same value gates both the listen
    # schema and its prompt guidance.
    listen_available: bool = True
    # True when this turn offers the ``set_fields`` tool (the active skill has
    # settable entries). Gates every prompt mention of ``set_fields`` so the
    # model is never told to call a tool absent from the schema.
    set_fields_available: bool = False
    skipped_collects: Tuple[SkippedCollectView, ...] = ()
    # FAISS ∩ legal startable ids for this LLM iteration, or ``None`` when
    # skill retrieval is off (prompt and ``activate`` stay on the full legal list).
    allowed_target_ids: Optional[Tuple[str, ...]] = None
    # False when this call's tool list does not include ``activate``. The
    # lifecycle prompt must not tell the model to call a tool it was not offered.
    activate_tool_available: bool = True


class PromptConstructor:
    """Builds LLM chat messages for one engine turn.

    Entry points assemble a system message, conversation history, and the
    current user turn for normal, rephrase, and memory-extraction calls.

    Budget contract: :meth:`build_messages` does **not** trim — the orchestrator
    is the single point that enforces :func:`trim_history_to_budget` after
    rebuilding history (including tool replay) from the tracker.
    Dedicated follow-up calls add a protected instruction suffix and trim
    themselves.
    """

    def build_messages(self, context: PromptContext) -> List[LlmMessage]:
        """Build system, history, and current-user messages for one LLM request.

        Returns the assembled messages untrimmed; the caller enforces the
        prompt token budget after rebuilding history from the tracker (see
        the budget contract in the class docstring).
        """
        messages = self._assemble_messages(context, build_system_prompt(context))
        reminder = skipped_collect_reminder(context.skipped_collects)
        if reminder:
            messages.append(llm_message(ROLE_SYSTEM, reminder))
        if canned_utter_delivered_this_turn(context.tracker):
            messages.append(llm_message(ROLE_SYSTEM, canned_utter_reminder()))
        written_key = context.turn.set_memory_button_written_key
        if written_key:
            messages.append(
                llm_message(
                    ROLE_SYSTEM,
                    set_memory_button_stored_instruction(written_key),
                )
            )
        return messages

    def build_rephrase_messages(
        self, context: PromptContext, text_to_rephrase: str
    ) -> List[LlmMessage]:
        """Build a message list that instructs the LLM to rephrase *text_to_rephrase*.

        A minimal system prompt (persona, rules, channel rules — no skills or
        tools) plus the standard conversation history, followed by a final
        system message carrying the rephrasing instruction.  Callers must
        suppress tools for this call (rephrase mode — no tool calls allowed).
        """
        messages = self._assemble_messages(
            context, build_rephrase_system_prompt(context)
        )
        instruction = render_template(
            REPHRASE_INSTRUCTION_TEMPLATE, text=text_to_rephrase
        )
        # Budget is applied AFTER appending the instruction so the trim accounts
        # for it (the instruction sits in the protected suffix and is kept).
        return self._trimmed_to_budget(
            [*messages, llm_message(ROLE_SYSTEM, instruction)], context
        )

    def build_set_fields_fill_messages(
        self, context: PromptContext
    ) -> List[LlmMessage]:
        """Build messages for a silent memory extraction call."""
        messages = self._assemble_messages(
            context, build_set_fields_fill_system_prompt()
        )
        instruction = render_template(SET_FIELDS_FILL_INSTRUCTION_TEMPLATE)
        return self._trimmed_to_budget(
            [*messages, llm_message(ROLE_SYSTEM, instruction)], context
        )

    def build_confirm_rephrase_messages(
        self,
        context: PromptContext,
        text_to_rephrase: str,
        *,
        field_name: str,
        value: object,
        field_description: Optional[str] = None,
    ) -> List[LlmMessage]:
        """Build messages for a filled collect confirmation-rephrase call."""
        field_label = field_description or field_name
        value_display = _format_confirm_rephrase_value(value)
        messages = self._assemble_messages(
            context, build_rephrase_system_prompt(context)
        )
        instruction = render_template(
            CONFIRM_REPHRASE_INSTRUCTION_TEMPLATE,
            field_label=field_label,
            value_display=value_display,
            text=text_to_rephrase,
        )
        return self._trimmed_to_budget(
            [*messages, llm_message(ROLE_SYSTEM, instruction)], context
        )

    def _assemble_messages(
        self, context: PromptContext, system_content: str
    ) -> List[LlmMessage]:
        """System message plus conversation history and the current user turn."""
        messages: List[LlmMessage] = [llm_message(ROLE_SYSTEM, system_content)]
        conversation, last_user_content = conversation_messages_from_tracker(
            context.tracker, max_utterances=context.max_utterances
        )
        if context.turn.suppress_llm_user_message:
            # History shows a set: tap as its button title, so matching the
            # raw payload would leave that title in a suppressed prompt.
            omitted = prompt_text_for_set_memory_utterance(
                context.turn.text, context.turn.metadata
            )
            if omitted:
                conversation, last_user_content = omit_trailing_user_text(
                    conversation, last_user_content, omitted
                )
        messages.extend(conversation)
        return append_current_user_message(messages, context.turn, last_user_content)

    @staticmethod
    def _trimmed_to_budget(
        messages: List[LlmMessage], context: PromptContext
    ) -> List[LlmMessage]:
        """Enforce the configured prompt token budget on a message list."""
        return trim_history_to_budget(
            messages,
            max_tokens=resolve_max_prompt_tokens(context.bootstrap.llm),
            model_name=resolve_llm_model_name(context.bootstrap.llm),
        )


def _format_confirm_rephrase_value(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if value == PII_SET_PLACEHOLDER:
        return PII_SET_PLACEHOLDER
    return render_memory_value(value)
